    cracker_patches = image_patch.find("crackers")
    pie_patches = image_patch.find("pie")

    if not cracker_patches or not pie_patches:
        return image_patch

    cracker_centers = [(p.left + p.right) / 2 for p in cracker_patches]
    pie_centers = [(p.left + p.right) / 2 for p in pie_patches]

    min_distance = float('inf')
    closest_cracker = None

    for cracker_center in cracker_centers:
        for pie_center in pie_centers:
            if cracker_center < pie_center:
                distance = pie_center - cracker_center
                if distance < min_distance:
                    min_distance = distance
                    closest_cracker = cracker_patches[cracker_centers.index(cracker_center)]

    return closest_cracker

