        ball_center = (ball.left + ball.right) / 2
        return abs(player_center - ball_center)

    baseball_player_patches[0].hand_patches = ball_patches
    ball_patches.sort(key=lambda ball: hand_distance(baseball_player_patches[0], ball))

    return ball_patches[0]

