    bowl_patches = image_patch.find("bowl")
    strawberry_patches = image_patch.find("strawberry")

    if not bowl_patches or not strawberry_patches:
        return image_patch

    bowl = bowl_patches[0]
    strawberries = sorted(strawberry_patches, key=lambda s: bowl.distance(s))

    for strawberry in strawberries:
        if bowl.contains(strawberry):
            return bowl.crop(bowl.left, bowl.lower, bowl.right, bowl.upper)

    return bowl

